import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=path=>readFileSync(path,'utf8');
const schema=read('supabase/migrations/20261124120000_pharmacy_partner_review_pilot.sql');
const api=read('app/api/admin/pharmacy/route.ts');
const landing=read('app/pharmacy/page.tsx');
const admin=read('app/admin/pharmacy/page.tsx');
const intake=read('app/components/PartnerLeadForm.tsx');
const backend=read('app/api/partners/route.ts');
const sitemap=read('app/sitemap.ts');
const home=read('app/page.tsx');
assert(schema.includes('create table if not exists public.pharmacy_partner_reviews'));
assert(schema.includes('enable row level security'));
assert(schema.includes('revoke all on table public.pharmacy_partner_reviews from public,anon,authenticated;'));
assert(schema.includes('grant select,insert,update,delete on table public.pharmacy_partner_reviews to service_role'));
assert(api.includes('requireMarketingAdmin(request)'));
assert(api.includes(".eq('partner_type','LICENSED_PHARMACY')"));
assert(api.includes("action==='status'"));
assert(api.includes("body.action!=='review'"));
assert(!api.includes('RAZORPAY')&&!api.includes('PAYMENT_SUCCESS')&&!api.includes('dispense'));
assert(landing.includes('Medicine ordering is not live'));
assert(landing.includes('Do not upload prescriptions'));
assert(landing.includes('₹299')&&landing.includes('0% Zeshu sales commission'));
assert(landing.includes("canonical: '/pharmacy'"));
assert(admin.includes('Save private review (no activation)'));
assert(intake.includes('isPharmacy')&&intake.includes('pharmacyAcknowledged'));
assert(backend.includes('partnerType === \'LICENSED_PHARMACY\''));
assert(sitemap.includes('"/pharmacy"'));
assert(home.includes("id: 'pharmacy', label: 'Zeshu Pharmacy'"));
console.log('PHARMACY_PILOT_QA=PASS: No Rx upload, no paid pharmacy checkout, locked admin review, no public medicine orders.');
